 static void CompareGeometry(GameObject a,GameObject b){var x=a.GetComponent<MeshFilter>().sharedMesh;var y=b.GetComponent<MeshFilter>().sharedMesh;Check(ColliderSnapshot109.MeshHash(x)==ColliderSnapshot109.MeshHash(y)&&x.uv.SequenceEqual(y.uv)&&x.normals.SequenceEqual(y.normals)&&x.colors.SequenceEqual(y.colors),"unchanged geometry/UV/normals/colour "+a.name);int count=a.GetComponentsInChildren<Collider>(true).Length;Check(count==b.GetComponentsInChildren<Collider>(true).Length,"collider count");if(count>0)Check(ColliderSnapshot109.Capture(a)==ColliderSnapshot109.Capture(b),"actual collider");var al=a.GetComponentsInChildren<Light>(true);var bl=b.GetComponentsInChildren<Light>(true);Check(al.Length==bl.Length,"lights count");for(int i=0;i<al.Length;i++)Check(al[i].type==bl[i].type&&al[i].intensity==bl[i].intensity&&al[i].range==bl[i].range&&al[i].color==bl[i].color&&al[i].transform.localPosition==bl[i].transform.localPosition,"light unchanged");}
 static void SetStage(GameObject o,int stage){var renderer=o.GetComponent<Renderer>();var previous=renderer.sharedMaterial;var m=new Material(previous);m.shader=Shader.Find(stage==0?"Review/SharedBefore117":"MapSharedProps/Lit");if(stage==1)m.EnableKeyword("SMALL_PROP_LOCAL_LIGHTS");else m.DisableKeyword("SMALL_PROP_LOCAL_LIGHTS");m.name="diagnostic117";renderer.sharedMaterial=m;if(previous.name=="diagnostic117")UnityEngine.Object.DestroyImmediate(previous);}
