   foreach(string id in Representatives){var o=(GameObject)PrefabUtility.InstantiatePrefab(prefabs[id]);foreach(var l in o.GetComponentsInChildren<Light>())l.enabled=false;var bounds=o.GetComponent<Renderer>().bounds;var target=bounds.center;float size=Mathf.Max(bounds.size.x,bounds.size.y,bounds.size.z);camera.transform.position=target+new Vector3(1.3f,1.2f,-2)*Mathf.Max(size,.5f);camera.transform.LookAt(target);camera.fieldOfView=38;Vector3 direction=new Vector3(-.6f,1,-.7f).normalized;
