     for(int stage=0;stage<2;stage++){SetStage(o,stage);var im=Shared117Review.Image(camera,480,360);pixels[stage]=im.EncodeToPNG();var colours=im.GetPixels();mean[stage]=colours.Sum(c=>(c.r+c.g+c.b)/3)/colours.Length;if((mode==2&&(lighting=="point"||id=="storagepot"&&(lighting=="spotShadow"||lighting=="day")))||(id=="lantern"&&lighting=="point"))File.WriteAllBytes(Path.Combine(output,id+"-"+lighting+"-"+(stage==0?"before":"after")+".png"),pixels[stage]);UnityEngine.Object.DestroyImmediate(im);Check(!ShaderUtil.ShaderHasError(o.GetComponent<Renderer>().sharedMaterial.shader),"shader compile "+id);}
     if(lighting=="off"||lighting=="day"||lighting=="ambient"||lighting=="spotOutside")Check(pixels[0].SequenceEqual(pixels[1]),"no-local pixels exact "+id+" "+lighting);if(lighting=="point"||lighting=="spot")Check(mean[1]>mean[0]+(id=="lantern"?.0001f:.001f),"local response "+id+" "+lighting+" before="+mean[0]+" after="+mean[1]);rows.Add(new Row{mode=mode.ToString(),id=id,light=lighting,before=mean[0],after=mean[1]});}
    Func<string,float> gain=kind=>{var row=rows.Last(x=>x.mode==mode.ToString()&&x.id==id&&x.light==kind);return row.after-row.before;};Check(gain("far")<gain("point")*.6f,"distance falloff "+id);Check(gain("pointShadow")<gain("point")*.3f&&gain("spotShadow")<gain("spot")*.3f,"local shadow attenuation "+id);UnityEngine.Object.DestroyImmediate(o.GetComponent<Renderer>().sharedMaterial);UnityEngine.Object.DestroyImmediate(o);
   }
   if(mode==2){sun.enabled=false;blocker.SetActive(false);RenderSettings.ambientLight=Color.black;local.enabled=true;local.type=LightType.Point;local.shadows=LightShadows.None;local.range=8;local.transform.position=new Vector3(0,3,0);var extra=new List<GameObject>();foreach(float x in new[]{-4f,4f}){var l=UnityEngine.Object.Instantiate(local.gameObject);l.transform.position=new Vector3(x,3,0);extra.Add(l);}foreach(int count in new[]{9,225}){var instances=new List<GameObject>();int side=(int)Mathf.Sqrt(count);for(int j=0;j<count;j++){var o=(GameObject)PrefabUtility.InstantiatePrefab(prefabs["smallbarrel"]);o.transform.position=new Vector3(j%side-side*.5f,0,j/side-side*.5f);instances.Add(o);}camera.transform.position=new Vector3(side*.8f,side*1.2f,-side*1.1f);camera.transform.LookAt(Vector3.zero);var rt=new RenderTexture(640,480,24);camera.targetTexture=rt;foreach(int stage in new[]{0,1}){foreach(var o in instances)SetStage(o,stage);for(int k=0;k<4;k++)camera.Render();var times=new List<double>();for(int k=0;k<9;k++){var sw=System.Diagnostics.Stopwatch.StartNew();camera.Render();sw.Stop();times.Add(sw.Elapsed.TotalMilliseconds);}times.Sort();timings.Add(new Timing{instances=count,stage=stage==0?"before":"after",cpuMedianMs=times[4]});}camera.targetTexture=null;rt.Release();UnityEngine.Object.DestroyImmediate(rt);foreach(var o in instances){UnityEngine.Object.DestroyImmediate(o.GetComponent<Renderer>().sharedMaterial);UnityEngine.Object.DestroyImmediate(o);}}foreach(var o in extra)UnityEngine.Object.DestroyImmediate(o);}
  }
  string legacyFolder="Assets/Imported117-legacy";Check(!AssetDatabase.IsValidFolder(legacyFolder),"fresh legacy");AssetDatabase.CreateFolder("Assets","Imported117-legacy");parent=new GameObject("legacy");var legacy=new Dictionary<string,GameObject>();LegacySmallProps114.Build(Path.Combine(Root,"Input114-after"),legacyFolder,parent.transform,Shader.Find("MapSharedProps/Lit"),legacy);Check(legacy.Count==43,"old source reader43");foreach(var item in legacy)CompareGeometry(prefabs[item.Key],item.Value);UnityEngine.Object.DestroyImmediate(parent);AssetDatabase.SaveAssets();
  File.WriteAllText(Path.Combine(output,"checks.json"),JsonUtility.ToJson(new Report{pass=true,prefabs=44,legacyPrefabs=43,optedIds=opted.ToArray(),rows=rows.ToArray(),timings=timings.ToArray(),limits=new[]{"Source reader control flow only; old binary not run","Forward/Forward+ per-pixel local-light setting only; vertex mode untested","CPU Camera.Render timings are short samples, not GPU/mobile benchmarks","Offscreen Editor only; Player/full gameplay not run"}},true));
 }catch(Exception e){Debug.LogException(e);File.WriteAllText(Path.Combine(output,"error.txt"),e.ToString());exit=1;}finally{EditorApplication.Exit(exit);}}
